text:
{
  "questions": [
    {
      "n": 1,
      "start": "Warum kann die Stadtgärtnerei ohne Rücksprache",
      "end": "mit den Riehener Behörden und ohne öffentliche Publikation Bäume auf Riehener Boden abholzen?"
    },
    {
      "n": 2,
      "start": "Beabsichtigt die Stadtgärtnerei weitere Baumfällungen auf Riehener Boden? Wo?",
      "end": "Wann? Ebenfalls ohne öffentliche Publikation?"
    },
    {
      "n": 3,
      "start": "Warum hat der Gemeinderat keine Massnahmen ergriffen, damit von unabhängiger Stelle der wirkliche Krankheitszustand der Bäume hätte festgestellt werden",
      "end": "können?"
    },
    {
      "n": 4,
      "start": "Was gedenkt der Gemeinderat zu unternehmen, damit diese Abholzmentalität",
      "end": "nicht umgesetzt wird?"
    },
    {
      "n": 5,
      "start": "Welche Pilzkrankheit hatten die Lindenbäume?",
      "end": ""
    },
    {
      "n": 6,
      "start": "Ist es ein Pilz der spezifisch Lindenbäume befällt?",
      "end": ""
    },
    {
      "n": 7,
      "start": "Laut Stadtgärtnerei sollen wieder Lindenbäume gepflanzt werden. Somit wären",
      "end": "auch diese Bäume wieder durch Pilzkrankheiten gefährdet?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Gemäss kantonalem Baumschutzgesetz werden Baumfällungen in der Baumschutzzone publiziert.",
      "end": "Auf dem Stadtgebiet gilt die Baumschutzzone flächendeckend."
    },
    {
      "n": 2,
      "start": "Weitere Baumfällungen sind gemäss Stadtgärtnerei aus heutiger Sicht nicht geplant.",
      "end": "Der Gemeinderat hat mit der Stadtgärtnerei Kontakt aufgenommen."
    },
    {
      "n": 3,
      "start": "Es gibt keinen Grund, an der fachlichen Qualität und am Vorgehen der Stadtgärtnerei zu zweifeln.",
      "end": "Die Stadtgärtnerei und die Gemeindegärtnerei fällen Bäume erst nach länger dauernder Beobachtung und nach kritischer Beurteilung durch verschiedene Fachinstanzen."
    },
    {
      "n": 4,
      "start": "Von einer Abholzmentalität kann sowohl bei der Stadtgärtnerei wie auch bei der Gemeindegärtnerei keine Rede sein.",
      "end": "Im Gegenteil werden Baumfällungen nur vorgenommen, wenn dies der Gesundheitszustand der Bäume und das Sicherheitsrisiko erfordern."
    },
    {
      "n": 5,
      "start": "Primäre Ursache des schlechten gesundheitlichen Zustands dieser Bäume ist die Sonnenbrandnekrose,",
      "end": "welche bereits vor mehreren Jahren festgestellt wurde."
    },
    {
      "n": 6,
      "start": "Wie unter 5. erwähnt, war die Hauptursache die Sonnenbrandnekrose.",
      "end": "Diese kann auch andere Baumsorten befallen."
    },
    {
      "n": 7,
      "start": "Die neugepflanzten Krimlinden sind bezüglich Hitze und Trockenheit wesentlich resistenter,",
      "end": "was insbesondere bei Strassenbäumen immer wichtiger wird."
    }
  ],
  "submitter": "Peter A. Vogt",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": null
}
